# Плечо в один конец ОТ БАЗЫ, а не от Екатеринбурга.
#
# distance_km выше отсчитывается от Екатеринбурга и нужен для текста
# («Тагил в 140 км»), а деньги считаются от площадки, с которой реально
# грузят этот товар. Баз три, и лежат они в разных концах области, поэтому
# одно число тут не работает: до Полевского от Курганово 25 км, а от
# Садового 60. Матрица расстояний и привязка товаров к базам — в bases.py.
from bases import KM as BASE_KM, BASES, PRODUCT_BASE, DEFAULT_BASE  # noqa

for _k, _c in CITIES.items():
    _c["base_km"] = BASE_KM[_k]          # {база: км в один конец}
